import { createHash } from 'node:crypto';
import { readdirSync, readFileSync, statSync } from 'node:fs';
const lines = [];
const walk = (p) => { let st; try { st = statSync(p); } catch { return; }
  if (st.isDirectory()) { for (const e of readdirSync(p)) walk(p + '/' + e); return; }
  lines.push(p + ' ' + createHash('sha1').update(readFileSync(p)).digest('hex')); };
for (const r of ['tests', 'docs', 'scripts', 'package.json']) walk(r);
console.log(createHash('sha1').update(lines.sort().join('\n')).digest('hex'));
